<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, getToken, setToken } from './api'
import { DataAnalysis, User, Setting, Monitor, Warning, SwitchButton, Refresh, Plus, Key, Location, Search, Clock } from '@element-plus/icons-vue'
type Row = Record<string, any>
type AdminUser = { id:string; username:string; email?:string; is_super_admin:boolean; status?:string; last_login_at?:string; permissions?:string[]|null }
type Permission = { key:string; name:string }
const token=ref(getToken()), currentUser=ref<AdminUser|null>(null), activePage=ref('overview'), loading=ref(false)
const users=ref<AdminUser[]>([]), permissions=ref<Permission[]>([])
const loginForm=reactive({username:'',password:''}), createForm=reactive({username:'',email:'',password:''}), passwordForm=reactive({current_password:'',new_password:''})
const createVisible=ref(false), permissionVisible=ref(false), passwordVisible=ref(false), selectedUser=ref<AdminUser|null>(null), selectedPermissions=ref<string[]>([])
const players=ref<Row[]>([]), online=ref<Row[]>([]), playerQuery=ref(''), playerDetail=ref<Row|null>(null), playerDetailVisible=ref(false), playerDetailTab=ref('overview')
const onlineFilter=reactive({q:'',world_id:'',node_key:''}), onlineTotal=ref(0), onlinePage=ref(1), onlinePageSize=ref(20)
const worlds=ref<Row[]>([]), instances=ref<Row[]>([]), selectedWorld=ref<Row|null>(null), instancesVisible=ref(false), servers=ref<Row[]>([])
const monsters=ref<Row[]>([]), spawns=ref<Row[]>([]), items=ref<Row[]>([]), loot=ref<Row[]>([]), revisions=ref<Row[]>([]), audits=ref<Row[]>([])
const auditFilter=reactive({actor_id:'',action:'',resource_type:'',resource_id:'',result:'',from:'',to:''})
const auditTotal=ref(0), auditPage=ref(1), auditPageSize=ref(20)
const monsterTab=ref('definitions'), revisionType=ref(''), revisionID=ref('')
const editorVisible=ref(false), editorTitle=ref(''), editorPath=ref(''), editorMethod=ref('PATCH'), editorJSON=ref('{}')
const lootVisible=ref(false), lootForm=reactive({monster_id:'',item_id:'',drop_chance_bp:1000,min_quantity:1,max_quantity:1})
const revisionDetail=ref<Row|null>(null), revisionDetailVisible=ref(false)
const revisionDiff=computed(()=>{const old=revisionDetail.value?.old_snapshot||{},next=revisionDetail.value?.new_snapshot||{};const keys=Array.from(new Set([...Object.keys(old),...Object.keys(next)]));return keys.filter(k=>JSON.stringify(old[k])!==JSON.stringify(next[k])).map(k=>({field:k,before:old[k],after:next[k]}))})
const overview=reactive({online:0,worlds:0,nodes:0})
const serviceHealth=ref<Row[]>([]), healthOverall=ref('unknown'), healthCheckedAt=ref('')
const playerGrowth=computed(()=>playerDetail.value?.game?.growth||{})
const superAdmin=computed(()=>!!currentUser.value?.is_super_admin)
const has=(p:string)=>superAdmin.value||!!currentUser.value?.permissions?.includes(p)
const menu=[
{id:'overview',label:'运营总览',icon:DataAnalysis,permission:'dashboard.read'},
{id:'service-health',label:'服务健康监控',icon:Monitor,permission:'dashboard.read'},
{id:'players',label:'玩家管理',icon:User,permission:'players.read'},
{id:'worlds',label:'世界管理',icon:Location,permission:'worlds.read'},
{id:'servers',label:'服务器监控',icon:Monitor,permission:'servers.read'},
{id:'monsters',label:'怪物与掉落',icon:Setting,permission:'monsters.read'},
{id:'revisions',label:'配置版本历史',icon:Clock,permission:'monsters.read'},
{id:'audit',label:'操作审计',icon:Warning,permission:'audit.read'},
{id:'users',label:'后台用户与权限',icon:User,permission:'admin_users.read'}]
const visibleMenu=computed(()=>menu.filter(x=>has(x.permission)))
const pageTitle=computed(()=>menu.find(x=>x.id===activePage.value)?.label||'运营总览')
const fmt=(v:any)=>v==null||v===''?'—':typeof v==='object'?JSON.stringify(v):String(v)
const tagType=(v:any)=>['ready','active','normal','success'].includes(String(v))?'success':['offline','disabled','locked','failure'].includes(String(v))?'danger':['draining','saving','pending'].includes(String(v))?'warning':'info'
async function login(){loading.value=true;try{const r=await api<any>('/api/v1/admin/auth/login',{method:'POST',body:JSON.stringify(loginForm)});setToken(r.access_token);token.value=r.access_token;currentUser.value=r.user;ElMessage.success('登录成功');await loadPage(visibleMenu.value[0]?.id||'overview')}catch(e){ElMessage.error(fmt((e as Error).message))}finally{loading.value=false}}
async function logout(show=true){if(token.value){try{await api('/api/v1/admin/auth/logout',{method:'POST'})}catch{}}setToken(null);token.value='';currentUser.value=null;if(show)ElMessage.success('已退出')}
async function restore(){if(!token.value)return;try{currentUser.value=await api<AdminUser>('/api/v1/admin/auth/me');const landing=visibleMenu.value.some(x=>x.id===activePage.value)?activePage.value:(visibleMenu.value[0]?.id||'overview');await loadPage(landing)}catch{await logout(false)}}
async function loadUsers(){if(has('admin_users.read'))users.value=(await api<any>('/api/v1/admin/users')).items||[]}
async function createUser(){try{const u=await api<AdminUser>('/api/v1/admin/users',{method:'POST',body:JSON.stringify(createForm)});createVisible.value=false;await loadUsers();if(has('admin_users.manage'))openPermissions(u);ElMessage.success('后台用户已创建')}catch(e){ElMessage.error((e as Error).message)}}
async function openPermissions(u:AdminUser){selectedUser.value=u;selectedPermissions.value=[...(u.permissions||[])];permissions.value=(await api<any>('/api/v1/admin/permissions')).items||[];permissionVisible.value=true}
async function savePermissions(){if(!selectedUser.value)return;try{await api('/api/v1/admin/users/'+selectedUser.value.id+'/permissions',{method:'PUT',body:JSON.stringify({permissions:selectedPermissions.value})});permissionVisible.value=false;await loadUsers();ElMessage.success('权限已更新')}catch(e){ElMessage.error((e as Error).message)}}
async function toggleAdminUserStatus(u:AdminUser){const next=u.status==='active'?'disabled':'active';try{await ElMessageBox.confirm('确定'+(next==='disabled'?'禁用':'重新启用')+'后台账号 '+u.username+'？'+(next==='disabled'?'禁用后该账号的现有会话会立即失效。':''),'确认账号状态');await api('/api/v1/admin/users/'+u.id+'/status',{method:'PATCH',body:JSON.stringify({status:next})});await loadUsers();ElMessage.success(next==='disabled'?'账号已禁用':'账号已启用')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error((e as Error).message||'状态更新失败')}}
async function changePassword(){try{const r=await api<any>('/api/v1/admin/auth/password',{method:'POST',body:JSON.stringify(passwordForm)});setToken(r.access_token);token.value=r.access_token;passwordVisible.value=false;ElMessage.success('密码已修改')}catch(e){ElMessage.error((e as Error).message)}}
async function loadPlayers(){const a=await api<any>('/api/v1/admin/players?q='+encodeURIComponent(playerQuery.value)+'&limit=100');players.value=a.items||[];await loadOnlinePlayers()}
async function loadOnlinePlayers(){const q=new URLSearchParams({limit:String(onlinePageSize.value),offset:String((onlinePage.value-1)*onlinePageSize.value)});Object.entries(onlineFilter).forEach(([k,v])=>{if(v.trim())q.set(k,v.trim())});const b=await api<any>('/api/v1/admin/players/online?'+q.toString());online.value=b.items||[];onlineTotal.value=b.total||0}
async function searchOnlinePlayers(){onlinePage.value=1;await loadOnlinePlayers()}
function resetOnlinePlayers(){Object.assign(onlineFilter,{q:'',world_id:'',node_key:''});onlinePage.value=1;void loadOnlinePlayers()}
async function changeOnlinePage(page:number){onlinePage.value=page;await loadOnlinePlayers()}
async function changeOnlinePageSize(size:number){onlinePageSize.value=size;onlinePage.value=1;await loadOnlinePlayers()}
async function showPlayer(row:Row){try{playerDetail.value=await api<Row>('/api/v1/admin/players/'+(row.id||row.account_id));playerDetailTab.value='overview';playerDetailVisible.value=true}catch(e){ElMessage.error((e as Error).message)}}
async function playerAction(row:Row,action:string){const id=row.id||row.account_id;try{if(action==='lock'){const r=await ElMessageBox.prompt('请输入封禁原因（2-300字）','封禁玩家');if(r.value.trim().length<2)throw new Error('封禁原因至少2个字');await api('/api/v1/admin/players/'+id+'/status',{method:'PATCH',body:JSON.stringify({status:'locked',reason:r.value})})}else if(action==='unlock'){await api('/api/v1/admin/players/'+id+'/status',{method:'PATCH',body:JSON.stringify({status:'active',reason:'管理员解除封禁'})})}else{await ElMessageBox.confirm('确定请求该玩家强制下线吗？','强制下线');await api('/api/v1/admin/players/'+id+'/disconnect',{method:'POST'})}ElMessage.success('操作已提交');await loadPlayers()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error((e as Error).message||'操作失败')}}
async function loadWorlds(){worlds.value=(await api<any>('/api/v1/admin/worlds')).items||[]}
async function showInstances(w:Row){selectedWorld.value=w;instances.value=(await api<any>('/api/v1/admin/worlds/'+w.id+'/instances')).items||[];instancesVisible.value=true}
async function toggleWorld(w:Row){try{await ElMessageBox.confirm('确定'+(w.enabled?'停用':'启用')+'世界 '+w.name+'？停用将触发会话优雅下线。','世界状态');await api('/api/v1/admin/worlds/'+w.id+'/state',{method:'PATCH',body:JSON.stringify({enabled:!w.enabled})});await loadWorlds();ElMessage.success('世界状态已更新')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error((e as Error).message)}}
async function loadServers(){servers.value=(await api<any>('/api/v1/admin/servers/nodes')).items||[]}
async function nodeState(n:Row,state:string){try{await api('/api/v1/admin/servers/nodes/'+encodeURIComponent(n.node_key)+'/state',{method:'PATCH',body:JSON.stringify({admin_state:state})});await loadServers();ElMessage.success('节点状态已更新')}catch(e){ElMessage.error((e as Error).message)}}
async function loadMonsters(){const [a,b,c,d]=await Promise.all([api<any>('/api/v1/admin/monsters/definitions'),api<any>('/api/v1/admin/monsters/spawn-points'),api<any>('/api/v1/admin/loot/items'),api<any>('/api/v1/admin/loot/tables')]);monsters.value=a.items||[];spawns.value=b.items||[];items.value=c.items||[];loot.value=d.entries||[]}
function editJSON(title:string,path:string,method:string,row?:Row){editorTitle.value=title;editorPath.value=path;editorMethod.value=method;const copy={...(row||{})};['created_at','updated_at','world_name','monster_name','level','id'].forEach(k=>delete copy[k]);editorJSON.value=JSON.stringify(copy,null,2);editorVisible.value=true}
async function saveJSON(){let body:Row;try{body=JSON.parse(editorJSON.value)}catch{ElMessage.error('JSON 格式错误');return}try{await api(editorPath.value,{method:editorMethod.value,body:JSON.stringify(body)});editorVisible.value=false;await loadMonsters();ElMessage.success('配置已保存')}catch(e){ElMessage.error((e as Error).message)}}
function editLoot(row?:Row){Object.assign(lootForm,row?{monster_id:row.monster_id,item_id:row.item_id,drop_chance_bp:row.drop_chance_bp,min_quantity:row.min_quantity,max_quantity:row.max_quantity}:{monster_id:monsters.value[0]?.id||'',item_id:items.value.find(x=>x.enabled)?.id||'',drop_chance_bp:1000,min_quantity:1,max_quantity:1});lootVisible.value=true}
async function saveLoot(){try{await api('/api/v1/admin/loot/tables/'+encodeURIComponent(lootForm.monster_id)+'/'+encodeURIComponent(lootForm.item_id),{method:'PUT',body:JSON.stringify({drop_chance_bp:lootForm.drop_chance_bp,min_quantity:lootForm.min_quantity,max_quantity:lootForm.max_quantity})});lootVisible.value=false;await loadMonsters();ElMessage.success('掉落配置已保存')}catch(e){ElMessage.error((e as Error).message)}}
async function deleteLoot(row:Row){try{await ElMessageBox.confirm('确定删除该掉落条目？','删除掉落');await api('/api/v1/admin/loot/tables/'+encodeURIComponent(row.monster_id)+'/'+encodeURIComponent(row.item_id),{method:'DELETE'});await loadMonsters()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error((e as Error).message)}}
async function loadRevisions(){const q=new URLSearchParams({limit:'100'});if(revisionType.value)q.set('resource_type',revisionType.value);if(revisionID.value)q.set('resource_id',revisionID.value);revisions.value=(await api<any>('/api/v1/admin/config-revisions?'+q)).items||[]}
async function rollback(r:Row){try{const answer=await ElMessageBox.prompt('请输入回滚原因（2-300字），该原因会写入版本历史和审计日志。','确认回滚',{inputValidator:v=>!!v&&v.trim().length>=2&&v.trim().length<=300,inputErrorMessage:'回滚原因需要 2-300 个字符'});await api('/api/v1/admin/config-revisions/'+r.id+'/rollback',{method:'POST',body:JSON.stringify({reason:answer.value})});await loadRevisions();ElMessage.success('已回滚')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error((e as Error).message)}}
async function loadAudit(){const q=new URLSearchParams({limit:String(auditPageSize.value),offset:String((auditPage.value-1)*auditPageSize.value)});Object.entries(auditFilter).forEach(([k,v])=>{if(v.trim())q.set(k,v.trim())});const page=await api<any>('/api/v1/admin/audit-logs?'+q.toString());audits.value=page.items||[];auditTotal.value=page.total||0}
async function searchAudit(){auditPage.value=1;await loadAudit()}
function resetAudit(){Object.assign(auditFilter,{actor_id:'',action:'',resource_type:'',resource_id:'',result:'',from:'',to:''});auditPage.value=1;void loadAudit()}
async function changeAuditPage(page:number){auditPage.value=page;await loadAudit()}
async function changeAuditPageSize(size:number){auditPageSize.value=size;auditPage.value=1;await loadAudit()}
async function loadServiceHealth(){const r=await api<any>('/api/v1/admin/services/health');serviceHealth.value=r.items||[];healthOverall.value=r.status||'unknown';healthCheckedAt.value=r.checked_at||''}
async function loadOverview(){const jobs:Promise<any>[]=[];if(has('admin_users.read'))jobs.push(loadUsers().catch(()=>{}));if(has('players.read'))jobs.push(api<any>('/api/v1/admin/players/online').then(r=>overview.online=r.total||0).catch(()=>overview.online=0));if(has('worlds.read'))jobs.push(api<any>('/api/v1/admin/worlds').then(r=>overview.worlds=(r.items||[]).filter((x:Row)=>x.enabled).length).catch(()=>overview.worlds=0));if(has('servers.read'))jobs.push(api<any>('/api/v1/admin/servers/nodes').then(r=>overview.nodes=(r.items||[]).filter((x:Row)=>x.status==='ready').length).catch(()=>overview.nodes=0));await Promise.all(jobs)}
async function loadPage(id:string){activePage.value=id;loading.value=true;try{if(id==='overview')await loadOverview();if(id==='service-health')await loadServiceHealth();if(id==='users')await loadUsers();if(id==='players')await loadPlayers();if(id==='worlds')await loadWorlds();if(id==='servers')await loadServers();if(id==='monsters')await loadMonsters();if(id==='revisions')await loadRevisions();if(id==='audit')await loadAudit()}catch(e){ElMessage.error((e as Error).message||'模块加载失败')}finally{loading.value=false}}
let healthTimer:ReturnType<typeof setInterval>|undefined
onMounted(()=>{restore();healthTimer=setInterval(()=>{if(currentUser.value&&activePage.value==='service-health'&&!loading.value)loadServiceHealth().catch(()=>{})},15000)})
onUnmounted(()=>{if(healthTimer)clearInterval(healthTimer)})
</script>
<template>
<div v-if="!currentUser" class="login-shell"><div class="login-glow"></div><div class="login-card"><div class="brand-mark">洪</div><div class="eyebrow">HONG HUANG WORLD · CONTROL CENTER</div><h1>洪荒世界管理中枢</h1><p class="login-subtitle">诸天运行 · 世界秩序 · 运营管理</p><el-form label-position="top" @submit.prevent="login"><el-form-item label="后台用户名"><el-input v-model="loginForm.username" size="large" autocomplete="username"/></el-form-item><el-form-item label="登录密码"><el-input v-model="loginForm.password" size="large" type="password" show-password autocomplete="current-password" @keyup.enter="login"/></el-form-item><el-button class="login-button" type="primary" size="large" :loading="loading" @click="login">进入管理中枢</el-button></el-form><div class="login-foot">独立管理账号 · 安全会话认证</div></div></div>
<el-container v-else class="admin-shell"><el-aside width="236px" class="sidebar"><div class="sidebar-brand"><div class="brand-mark small">洪</div><div><strong>洪荒管理中枢</strong><small>ADMIN CONSOLE</small></div></div><div class="nav-caption">管理工作台</div><el-menu :default-active="activePage" class="side-menu" @select="loadPage"><el-menu-item v-for="m in visibleMenu" :key="m.id" :index="m.id"><el-icon><component :is="m.icon"/></el-icon><span>{{m.label}}</span></el-menu-item></el-menu><div class="sidebar-bottom"><div class="connection-dot"></div><span>管理 API 已连接</span><span class="api-port">8790</span></div></el-aside>
<el-container class="main-container"><el-header class="topbar"><div><div class="breadcrumb">洪荒世界 <span>/</span> {{pageTitle}}</div><div class="topbar-title">{{pageTitle}}</div></div><div class="top-actions"><el-tag effect="dark" type="success" round>{{superAdmin?'超级管理员':'运营用户'}}</el-tag><el-dropdown><div class="profile"><el-avatar :size="34">{{currentUser.username.slice(0,1).toUpperCase()}}</el-avatar><div class="profile-name">{{currentUser.username}}</div></div><template #dropdown><el-dropdown-menu><el-dropdown-item @click="passwordVisible=true"><el-icon><Key/></el-icon>修改密码</el-dropdown-item><el-dropdown-item divided @click="logout()"><el-icon><SwitchButton/></el-icon>退出登录</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></el-header>
<el-main class="content" v-loading="loading">
<template v-if="activePage==='overview'"><div class="welcome-row"><div><h2>欢迎回来，{{currentUser.username}}</h2><p>实时掌握玩家、世界与服务器运行情况。</p></div><el-button :icon="Refresh" circle @click="loadPage('overview')"/></div><div class="metric-grid"><div class="metric-card"><div class="metric-label">当前在线玩家</div><div class="metric-value">{{overview.online}}</div><div class="metric-note">Game 实时会话统计</div></div><div class="metric-card"><div class="metric-label">已启用世界</div><div class="metric-value">{{overview.worlds}}</div><div class="metric-note">世界定义状态</div></div><div class="metric-card"><div class="metric-label">正常运行节点</div><div class="metric-value">{{overview.nodes}}</div><div class="metric-note">30 秒内有效心跳</div></div><div class="metric-card"><div class="metric-label">后台管理员</div><div class="metric-value">{{users.length||'—'}}</div><div class="metric-note">独立账号体系</div></div></div><section class="panel"><div class="panel-heading"><div><h3>运营工作台</h3><p>选择需要管理的业务模块</p></div></div><div class="module-links"><el-button v-for="m in visibleMenu.filter(x=>x.id!=='overview')" :key="m.id" @click="loadPage(m.id)">{{m.label}}</el-button></div></section></template>
<template v-else-if="activePage==='service-health'">
<div class="welcome-row"><div><h2>四大服务健康监控</h2><p>分别检查服务 HTTP 就绪状态与对应数据库连接；故障不会级联阻断其他服务。</p></div><el-button :icon="Refresh" @click="loadServiceHealth">立即刷新</el-button></div>
<section class="health-grid"><article v-for="item in serviceHealth" :key="item.name" class="health-card"><div class="health-card-head"><div><div class="health-name">{{item.name==='identity'?'Identity 身份服务':item.name==='game'?'Game 游戏服务':item.name==='chat'?'Chat 聊天服务':'Admin 管理服务'}}</div><div class="health-subtitle">{{item.name.toUpperCase()}} SERVICE</div></div><el-tag :type="item.status==='healthy'?'success':'danger'" effect="dark">{{item.status==='healthy'?'运行正常':'异常'}}</el-tag></div><div class="health-latency">{{item.latency_ms??0}}<small> ms</small></div><div class="health-foot"><span>最近检查 {{item.checked_at?new Date(item.checked_at).toLocaleTimeString():'—'}}</span><span>{{item.status==='healthy'?'HTTP /ready 正常':item.error||'无法连接'}}</span></div></article></section>
<section class="panel"><div class="panel-heading"><div><h3>监控汇总</h3><p>整体状态：<el-tag :type="healthOverall==='healthy'?'success':'danger'">{{healthOverall==='healthy'?'全部正常':'存在异常'}}</el-tag></p></div><span class="health-refresh-time">每 15 秒自动刷新 · 检查时间：{{healthCheckedAt?new Date(healthCheckedAt).toLocaleString():'—'}}</span></div><p class="dialog-hint">每次点击刷新都会并行检查四个服务。单个服务不可用时，仅标记该服务异常；Admin 健康接口仍返回检查结果。</p></section>
</template>
<template v-else-if="activePage==='users'"><div class="welcome-row"><div><h2>后台用户与权限</h2><p>后台账号与游戏玩家账号相互独立。</p></div><el-button v-if="has('admin_users.manage')" type="primary" :icon="Plus" @click="createVisible=true">创建后台用户</el-button></div><section class="panel table-panel"><el-table :data="users"><el-table-column prop="username" label="用户名"/><el-table-column prop="email" label="邮箱"/><el-table-column label="类型"><template #default="{row}"><el-tag>{{row.is_super_admin?'超级管理员':'普通用户'}}</el-tag></template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="tagType(row.status)">{{row.status==='active'?'启用':row.status==='disabled'?'禁用':row.status||'—'}}</el-tag></template></el-table-column><el-table-column label="最后登录" min-width="170"><template #default="{row}">{{row.last_login_at?new Date(row.last_login_at).toLocaleString():'从未登录'}}</template></el-table-column><el-table-column label="权限" min-width="260"><template #default="{row}"><el-tag v-for="p in row.permissions||[]" :key="p" size="small" class="tag-gap">{{p}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button v-if="has('admin_users.manage')&&!row.is_super_admin&&row.status==='active'" link type="primary" @click="openPermissions(row)">分配权限</el-button><el-button v-if="has('admin_users.manage')&&!row.is_super_admin&&row.id!==currentUser?.id" link :type="row.status==='active'?'danger':'success'" @click="toggleAdminUserStatus(row)">{{row.status==='active'?'禁用':'启用'}}</el-button></template></el-table-column></el-table></section></template>
