<el-dialog v-model="instancesVisible" :title="'世界实例 · '+(selectedWorld?.name||'')" width="900px"><el-table :data="instances"><el-table-column prop="instance_key" label="实例"/><el-table-column prop="effective_status" label="状态"/><el-table-column prop="node_key" label="节点"/><el-table-column prop="host" label="地址"/><el-table-column prop="udp_port" label="端口"/><el-table-column prop="active_sessions" label="在线"/><el-table-column prop="pending_sessions" label="待处理"/><el-table-column prop="last_heartbeat_at" label="最后心跳"/></el-table></el-dialog>
<el-dialog v-model="editorVisible" :title="editorTitle" width="700px"><p class="dialog-hint">按接口字段编辑 JSON。新增时需填写全部必需字段；编辑时只需填写要修改的字段。</p><el-input v-model="editorJSON" type="textarea" :rows="18"/><template #footer><el-button @click="editorVisible=false">取消</el-button><el-button type="primary" @click="saveJSON">保存</el-button></template></el-dialog>
<el-dialog v-model="lootVisible" title="掉落配置" width="500px"><el-form label-position="top"><el-form-item label="怪物"><el-select v-model="lootForm.monster_id" filterable><el-option v-for="m in monsters" :key="m.id" :label="m.name+' · '+m.id" :value="m.id"/></el-select></el-form-item><el-form-item label="物品"><el-select v-model="lootForm.item_id" filterable><el-option v-for="i in items.filter(x=>x.enabled)" :key="i.id" :label="i.name+' · '+i.id" :value="i.id"/></el-select></el-form-item><el-form-item label="概率（万分比）"><el-input-number v-model="lootForm.drop_chance_bp" :min="0" :max="10000"/></el-form-item><el-form-item label="最少数量"><el-input-number v-model="lootForm.min_quantity" :min="1"/></el-form-item><el-form-item label="最多数量"><el-input-number v-model="lootForm.max_quantity" :min="1"/></el-form-item></el-form><template #footer><el-button @click="lootVisible=false">取消</el-button><el-button type="primary" @click="saveLoot">保存</el-button></template></el-dialog>
<el-dialog v-model="revisionDetailVisible" title="版本差异与快照" width="820px"><template v-if="revisionDetail"><p class="dialog-hint">操作原因：{{revisionDetail.reason||"未填写（历史版本）"}}</p><h4>字段差异</h4><el-table :data="revisionDiff" empty-text="该版本没有字段差异"><el-table-column prop="field" label="字段" width="180"/><el-table-column label="修改前" min-width="220"><template #default="{row}">{{JSON.stringify(row.before)}}</template></el-table-column><el-table-column label="修改后" min-width="220"><template #default="{row}">{{JSON.stringify(row.after)}}</template></el-table-column></el-table><h4>修改前快照</h4><pre class="json-preview">{{JSON.stringify(revisionDetail.old_snapshot,null,2)}}</pre><h4>修改后快照</h4><pre class="json-preview">{{JSON.stringify(revisionDetail.new_snapshot,null,2)}}</pre></template></el-dialog>
</template>